# owner: platform
"""Contact sheet rows for substitute teachers."""


def _check(students):
    if not students:
        raise ValueError("no students to list")
    for stud in students:
        if not stud.email:
            name = stud.display_name
            raise ValueError(f"no email for {name}")


def _widths(cells):
    return [
        max(len(line[slot]) for line in cells)
        for slot in range(3)
    ]


def _pad(line, widths):
    pairs = zip(line, widths)
    text = "  ".join(
        item.ljust(size) for item, size in pairs
    )
    return text.rstrip()


def _cells(students):
    ordered = sorted(students, key=_name)
    return [
        (stud.display_name, stud.section, stud.email)
        for stud in ordered
    ]


def _name(stud):
    return stud.display_name


# ---
def format_contacts(students):
    """Name, section and email rows, sorted by name."""
    _check(students)
    cells = _cells(students)
    widths = _widths(cells)
    return [_pad(line, widths) for line in cells]

