# owner: platform
import unittest

from rosterkit.contacts import format_contacts
from rosterkit.models import Student


def _stud(last, first, section, email="x@example.com"):
    return Student("id", last, first, section, email)

EXPECTED = [
    "Adams, Beth  A  beth@example.com",
    "Young, Al    B  al@example.com",
]


class ContactTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = format_contacts([
            _stud("Young", "Al", "B", "al@example.com"),
            _stud("Adams", "Beth", "A", "beth@example.com"),
        ])
        self.assertEqual(rows, EXPECTED)

    def test_missing_email_names_student(self):
        blank = [_stud("Adams", "Beth", "A", "")]
        with self.assertRaises(ValueError) as caught:
            format_contacts(blank)
        self.assertIn("Adams, Beth", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            format_contacts([])
